// ─────────────────────────────────────────────────────────────────────────────
// Opportunities & Competitions Database — a curated reference library of real,
// well-established programs (competitions, research, volunteering, leadership,
// academic honors, and summer pipeline programs) a pre-health high schooler is
// likely to actually be eligible for. Searchable from the Portfolio Overview
// tab (see src/components/OpportunitiesDatabase.jsx), the same integrity bar
// as src/data/scholarships.js:
//
//   - Every entry is a real, independently-verifiable program — no invented
//     names, no fabricated URLs. Deliberately NO `url` field (unlike
//     scholarships.js): many of these programs vary by state/chapter/hospital,
//     so a single hardcoded link risks going stale or pointing at the wrong
//     local chapter — students should search the program's exact name plus
//     their state/city rather than follow a link that could rot.
//   - Deadlines, stipends, and exact eligibility windows shift year to year
//     and program to program — `eligibility` below is deliberately a general
//     description (age/grade range, typical prerequisites), not a promise.
//   - This is a curated ~150-program reference set, not an exhaustive index —
//     no database achieves that. Students can add anything not listed here as
//     a custom Portfolio activity.
//   - For-profit "pay to attend" youth leadership summits (the kind aggressively
//     marketed directly to teens by mail/email) are deliberately excluded, same
//     spirit as the paywall/fake-testimonial screens already removed from
//     onboarding (see Onboarding.jsx's header comment) — every entry here is
//     either free, need-based-supported, or merit-selective.
//
// ── Extended schema (added with the Portfolio tracking rebuild) ──────────────
// Entries may carry four extra facets beyond the original name/org/type/level/effort/desc/
// eligibility/tags set. They are OPTIONAL and deliberately so: they are only present where the
// value is genuinely stable year to year, because the whole integrity premise of this file is
// that we do not state things with more confidence than they deserve.
//
//   season   — when it runs or when you apply     (OPPORTUNITY_SEASONS)
//   cost     — what participating costs a student (OPPORTUNITY_COSTS)
//   format   — in person / virtual / hybrid       (OPPORTUNITY_FORMATS)
//   grades   — grade levels typically eligible    (subset of ['9','10','11','12'])
//
// `cost` is the facet students actually filter on and the one most likely to be wrong if
// guessed, so it is never inferred: an entry without a confirmed cost model simply omits the
// field, and the UI reports those as "not listed" rather than folding them into "Free".
import { OPPORTUNITIES_EXPANSION } from './opportunitiesExpansion.js';
import { OPPORTUNITIES_COMPETITIONS } from './opportunitiesCompetitions.js';

export const OPPORTUNITY_TYPES = ['All', 'Competition', 'Research', 'Scholarship', 'Volunteering', 'Organization', 'Academic', 'Program'];
export const OPPORTUNITY_LEVELS = ['National', 'International', 'State', 'Regional', 'Local'];
export const OPPORTUNITY_SEASONS = ['Summer', 'School year', 'Year-round', 'Fall', 'Winter', 'Spring', 'Varies'];
export const OPPORTUNITY_COSTS = ['Free', 'Free + stipend', 'Paid role', 'Entry fee', 'Tuition (aid available)', 'Varies'];
export const OPPORTUNITY_FORMATS = ['In person', 'Virtual', 'Hybrid', 'Varies'];
export const OPPORTUNITY_GRADES = ['9', '10', '11', '12'];

/** True when `entry` is open to a student in `grade` (an entry with no `grades` is open to all). */
export function fitsGrade(entry, grade) {
  if (!grade || !entry?.grades?.length) return true;
  return entry.grades.includes(String(grade));
}

/**
 * Counts of each value of `facet` across `entries`, plus how many omit it entirely. Drives the
 * filter chips' counts — and the honest "N don't list this" line beside them.
 */
export function facetCounts(entries, facet) {
  const counts = {};
  let missing = 0;
  for (const e of entries) {
    const v = e[facet];
    if (!v) { missing += 1; continue; }
    counts[v] = (counts[v] || 0) + 1;
  }
  return { counts, missing };
}

